import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC23%E7%AB%A0%20%E7%BB%84%E7%BB%87%E9%80%9A%E7%94%A8%E7%AE%A1%E7%90%86/23.1%20%E7%AE%A1%E7%90%86%E5%AD%A6%E5%9F%BA%E7%A1%80.html","title":"23.1 管理学基础","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第23章 组织通用管理/23.1 管理学基础.md"}`),a={name:`23.1 管理学基础.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_23-1-管理学基础" tabindex="-1"><a class="header-anchor" href="#_23-1-管理学基础"><span>23.1 管理学基础</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>管理学基础是指管理的基本原理、理论和方法，用于指导组织的管理实践。</p><h2 id="管理职能" tabindex="-1"><a class="header-anchor" href="#管理职能"><span>管理职能</span></a></h2><h3 id="_1-计划" tabindex="-1"><a class="header-anchor" href="#_1-计划"><span>1. 计划</span></a></h3><ul><li><strong>定义</strong>：制定组织目标和计划</li><li><strong>内容</strong>：战略规划、战术计划</li></ul><h3 id="_2-组织" tabindex="-1"><a class="header-anchor" href="#_2-组织"><span>2. 组织</span></a></h3><ul><li><strong>定义</strong>：安排组织资源和结构</li><li><strong>内容</strong>：组织结构设计、职责分工</li></ul><h3 id="_3-领导" tabindex="-1"><a class="header-anchor" href="#_3-领导"><span>3. 领导</span></a></h3><ul><li><strong>定义</strong>：指导和激励员工</li><li><strong>内容</strong>：领导风格、激励机制</li></ul><h3 id="_4-控制" tabindex="-1"><a class="header-anchor" href="#_4-控制"><span>4. 控制</span></a></h3><ul><li><strong>定义</strong>：监控和调整组织活动</li><li><strong>内容</strong>：绩效监控、偏差纠正</li></ul><h2 id="管理理论" tabindex="-1"><a class="header-anchor" href="#管理理论"><span>管理理论</span></a></h2><h3 id="_1-科学管理理论" tabindex="-1"><a class="header-anchor" href="#_1-科学管理理论"><span>1. 科学管理理论</span></a></h3><ul><li><strong>代表人物</strong>：泰勒</li><li><strong>核心</strong>：科学方法提高效率</li></ul><h3 id="_2-行为科学理论" tabindex="-1"><a class="header-anchor" href="#_2-行为科学理论"><span>2. 行为科学理论</span></a></h3><ul><li><strong>代表人物</strong>：梅奥</li><li><strong>核心</strong>：关注人的行为和需求</li></ul><h3 id="_3-系统管理理论" tabindex="-1"><a class="header-anchor" href="#_3-系统管理理论"><span>3. 系统管理理论</span></a></h3><ul><li><strong>核心</strong>：将组织视为系统</li><li><strong>应用</strong>：整体优化</li></ul><h3 id="_4-权变管理理论" tabindex="-1"><a class="header-anchor" href="#_4-权变管理理论"><span>4. 权变管理理论</span></a></h3><ul><li><strong>核心</strong>：根据环境调整管理方法</li><li><strong>应用</strong>：灵活适应</li></ul><h2 id="管理方法" tabindex="-1"><a class="header-anchor" href="#管理方法"><span>管理方法</span></a></h2><h3 id="_1-目标管理-mbo" tabindex="-1"><a class="header-anchor" href="#_1-目标管理-mbo"><span>1. 目标管理（MBO）</span></a></h3><ul><li><strong>特点</strong>：以目标为导向</li><li><strong>步骤</strong>：目标设定、目标实施、目标评估</li></ul><h3 id="_2-全面质量管理-tqm" tabindex="-1"><a class="header-anchor" href="#_2-全面质量管理-tqm"><span>2. 全面质量管理（TQM）</span></a></h3><ul><li><strong>特点</strong>：全员参与质量改进</li><li><strong>核心</strong>：持续改进</li></ul><h3 id="_3-流程再造-bpr" tabindex="-1"><a class="header-anchor" href="#_3-流程再造-bpr"><span>3. 流程再造（BPR）</span></a></h3><ul><li><strong>特点</strong>：重新设计业务流程</li><li><strong>目标</strong>：提高效率</li></ul><h2 id="管理的原则" tabindex="-1"><a class="header-anchor" href="#管理的原则"><span>管理的原则</span></a></h2><h3 id="_1-统一指挥" tabindex="-1"><a class="header-anchor" href="#_1-统一指挥"><span>1. 统一指挥</span></a></h3><ul><li>每个员工只接受一个上级的指挥</li><li>避免多头领导</li></ul><h3 id="_2-分工协作" tabindex="-1"><a class="header-anchor" href="#_2-分工协作"><span>2. 分工协作</span></a></h3><ul><li>明确分工</li><li>加强协作</li></ul><h3 id="_3-权责一致" tabindex="-1"><a class="header-anchor" href="#_3-权责一致"><span>3. 权责一致</span></a></h3><ul><li>权力与责任匹配</li><li>明确职责</li></ul><h3 id="_4-效率优先" tabindex="-1"><a class="header-anchor" href="#_4-效率优先"><span>4. 效率优先</span></a></h3><ul><li>追求效率</li><li>优化资源配置</li></ul><h2 id="管理学基础的重要性" tabindex="-1"><a class="header-anchor" href="#管理学基础的重要性"><span>管理学基础的重要性</span></a></h2><h3 id="_1-指导实践" tabindex="-1"><a class="header-anchor" href="#_1-指导实践"><span>1. 指导实践</span></a></h3><ul><li>为管理实践提供理论指导</li><li>提高管理效率</li></ul><h3 id="_2-培养能力" tabindex="-1"><a class="header-anchor" href="#_2-培养能力"><span>2. 培养能力</span></a></h3><ul><li>培养管理者的管理能力</li><li>提高决策水平</li></ul><h3 id="_3-适应变化" tabindex="-1"><a class="header-anchor" href="#_3-适应变化"><span>3. 适应变化</span></a></h3><ul><li>帮助组织适应环境变化</li><li>增强竞争力</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>管理职能</strong></li><li><strong>管理理论</strong></li><li><strong>管理方法</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>管理职能四方面，计划组织领导控制要做好，理论方法要记牢</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：管理的四大职能不包括以下哪项？ A. 计划 B. 组织 C. 领导 D. 生产</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>：管理的四大职能是计划、组织、领导和控制。生产不属于管理职能。</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};